        if (q.empty()) std::printf("%-26s L13:0x%08x  no moby of class 388 on this level\n", "hud_245cf8", 0x00245cf8);
        else
            l13check("hud_245cf8", 0x00245cf8, 120, Ret::None, [level, q] {
                level();
                const uint32_t e = OV(0x0017dc50) + u(ri(0, 12)) * 0x90;
                const uint32_t m = q[0];
                const uint32_t pv = ee_read<uint32_t>(m + 0x78);
                w32(e + 0xc, pv + 0x108);
                w32(e + 0x18, 0x00245cf8u);
                if (coin()) w32(e + 0x24, u(ri(0, 0x40)));
                for (uint32_t o = 0x108; o < 0x128; o += 4) if (ri(0, 3) == 0) w32(pv + o, u(ri(0, 0x780)));
                w32(OV(0x001611c0), 0x00800000u);
                w32(OV(0x0015f5cc), R());
                return Args{{e}, {}};
            }, [](A a) { boss_health_bar_draw(a.i[0]); return uint64_t{0}; });
